new="const artifactIdFor=()=>`${String(current.job.JOB_ID||'JOB').replace(/[^A-Za-z0-9-]/g,'')}-ARTIFACT-${crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2,8)}`}`;\nfunction logicalFilePath(file){const supplied=String(file?.webkitRelativePath||'').replaceAll('\\\\','/').replace(/^\\/+/,''),fallback=String(file?.name||'').replaceAll('\\\\','/').replace(/^\\/+/,''),raw=supplied||fallback,parts=raw.split('/').filter(Boolean);if(!parts.length||parts.some(part=>part==='.'||part==='..'))throw new Error('Artifact logical path is missing or unsafe.');const logical=supplied&&parts.length>1?parts.slice(1).join('/'):parts.join('/');if(!logical)throw new Error('Artifact logical path is missing.');return logical;}\nasync function storeArtifactFile(file,stage=current.activeStage){const artifactId=artifactIdFor(),filename=logicalFilePath(file),blob=file.slice(0,file.size,file.type||'application/octet-stream'),stored=await projectStore.putArtifact({artifactId,jobId:current.job.JOB_ID,blob,filename,mediaType:file.type||'application/octet-stream',lineage:{stage,role:core.STAGES[stage-1]?.role||'UNKNOWN',logicalPath:filename}});return {stored,view:{artifactId,name:stored.filename,type:stored.mediaType,size:stored.byteSize,sha256:stored.sha256,stage:`STAGE ${String(stage).padStart(2,'0')}`,role:core.STAGES[stage-1]?.role||'UNKNOWN',retainedBytes:true,availability:'IndexedDB Blob bytes persisted and rehashed on read-back.',addedAt:new Date().toISOString()}};}\nasync function registerStageFiles(fileList){const stage=current.activeStage,created=[];try{const paths=fileList.map(logicalFilePath);if(new Set(paths).size!==paths.length)throw new Error('Selected artifact package contains duplicate logical paths. Use the folder picker for structured packages so directory identity is preserved.');for(const file of fileList)created.push(await storeArtifactFile(file,stage));const next=clone(current);for(const item of created){const stored=item.stored;engine.registerArtifactBytes(next,{stage,artifactId:stored.artifactId,filename:stored.filename,mediaType:stored.mediaType,byteSize:stored.byteSize,sha256:stored.sha256,lineage:stored.lineage});next.stages[stage].authorizedFiles.push(item.view);}await persistReplacement(next);announce('artifact bytes saved and verified');render();}catch(error){for(const item of created)try{await projectStore.deleteArtifact?.(item.stored.artifactId,current.job.JOB_ID);}catch{}announce('storage failed');alert(`Artifact storage failed without authorizing metadata-only state: ${error.message||error}`);}}\nasync function digestFile(file){const bytes=await file.arrayBuffer(),sha256=await globalThis.closedLoopHash.sha256Bytes(bytes);return {name:logicalFilePath(file),type:file.type||'application/octet-stream',size:file.size,sha256};}"
